import re, json, csv

def get_md():
    d={}
    p = re.compile(r"- \*\*audit-v2-s03-t02-0*(\d+)\*\* \| System: [a-z0-9_-]+ \| Status: [a-z-]+ \| Evidence: (.+)\n?$")
    for line in open("audit-v2-s03-t02-evidence-01.md"):
        m = p.match(line)
        if m: d[int(m.group(1))] = m.group(2).rstrip()
    return d

def get_jsonl():
    d={}
    for line in open("audit-v2-s03-t02-evidence-02.jsonl"):
        j = json.loads(line)
        n = int(j["case"].split("-")[-1])
        d[n] = j["note"]
    return d

def get_csv():
    d={}
    with open("audit-v2-s03-t02-evidence-03.csv") as f:
        for row in csv.DictReader(f):
            n = int(row["case"].split("-")[-1])
            d[n] = row["note"]
    return d

def get_yaml():
    d={}
    cur={}
    lines = open("audit-v2-s03-t02-evidence-04.yaml").read().splitlines()
    for line in lines[1:]:
        s = line.strip()
        if s.startswith("- case:"):
            if cur: d[cur["n"]] = cur["note"]
            cur = {"n": int(s.split("-")[-1])}
        elif s.startswith("note:"):
            cur["note"] = s.split(":",1)[1].strip().strip('"')
    if cur: d[cur["n"]] = cur["note"]
    return d

def get_log():
    d={}
    p = re.compile(r'case=audit-v2-s03-t02-0*(\d+) system=[a-z0-9_-]+ status=[a-z-]+ note="(.+)"\n?$')
    for line in open("audit-v2-s03-t02-evidence-05.log"):
        m = p.match(line)
        if m: d[int(m.group(1))] = m.group(2)
    return d

sets = {"md": get_md(), "jsonl": get_jsonl(), "csv": get_csv(), "yaml": get_yaml(), "log": get_log()}
for name, d in sets.items():
    print(name, "count:", len(d))

common_ids = set.intersection(*(set(d.keys()) for d in sets.values()))
print("common ids across all 5 files:", min(common_ids), "-", max(common_ids), "count:", len(common_ids))

mismatches = 0
for i in common_ids:
    vals = {name: d[i] for name, d in sets.items()}
    if len(set(vals.values())) != 1:
        mismatches += 1
        if mismatches <= 3:
            print("MISMATCH at", i, vals)
print("total note mismatches across common ids:", mismatches)
