DIR=/private/var/folders/sp/k4h4yd5j4bj0zwbwzps0yj8c0000gp/T/lcm-live-92o2us9p/audit-v2-s03/maintenance/inputs/audit-v2-s03/cohort-inventory
python3 -c "
import json, re, csv

def parse_md(path):
    out = {}
    for line in open(path, encoding='utf-8'):
        m = re.match(r'- \*\*(audit-v2-s03-t04-\d{6})\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.*)', line.strip())
        if m:
            out[m.group(1)] = (m.group(2), m.group(3), m.group(4))
    return out

def parse_jsonl(path):
    out = {}
    for line in open(path, encoding='utf-8'):
        line = line.strip()
        if not line: continue
        d = json.loads(line)
        out[d['case']] = (d['system'], d['status'], d['note'])
    return out

def parse_csv(path):
    out = {}
    with open(path, newline='', encoding='utf-8') as f:
        for row in csv.DictReader(f):
            out[row['case']] = (row['system'], row['status'], row['note'])
    return out

def parse_yaml(path):
    out = {}
    case = system = status = None
    note = None
    for line in open(path, encoding='utf-8'):
        line = line.rstrip('\n')
        if line.startswith('- case:'):
            case = line.split(':',1)[1].strip()
        elif line.strip().startswith('system:'):
            system = line.split(':',1)[1].strip()
        elif line.strip().startswith('status:'):
            status = line.split(':',1)[1].strip()
        elif line.strip().startswith('note:'):
            note = line.split(':',1)[1].strip().strip('\"')
            out[case] = (system, status, note)
    return out

def parse_log(path):
    out = {}
    for line in open(path, encoding='utf-8'):
        line = line.strip()
        m = re.match(r'case=(\S+) system=(\S+) status=(\S+) note=\"(.*)\"', line)
        if m:
            out[m.group(1)] = (m.group(2), m.group(3), m.group(4))
    return out

md = parse_md('$DIR/audit-v2-s03-t04-evidence-01.md')
jl = parse_jsonl('$DIR/audit-v2-s03-t04-evidence-02.jsonl')
cs = parse_csv('$DIR/audit-v2-s03-t04-evidence-03.csv')
ym = parse_yaml('$DIR/audit-v2-s03-t04-evidence-04.yaml')
lg = parse_log('$DIR/audit-v2-s03-t04-evidence-05.log')

print('counts', len(md), len(jl), len(cs), len(ym), len(lg))

cycle = ['linux-x86_64','windows-x86_64','freebsd-x86_64','macos-arm64']
statuses = ['review','recorded','follow-up','supported']

def check_cycle(d, name):
    bad = 0
    for case, (system, status, note) in d.items():
        n = int(case.split('-')[-1])
        expected_system = cycle[(n-1) % 4]
        expected_status = statuses[(n-1) % 4]
        if system != expected_system or status != expected_status:
            bad += 1
    print(name, 'cycle violations:', bad)

check_cycle(md, 'md')
check_cycle(jl, 'jsonl')
check_cycle(cs, 'csv')
check_cycle(ym, 'yaml')
check_cycle(lg, 'log')

# overlap note agreement across all 5 files for common case IDs
common = set(md) & set(jl) & set(cs) & set(ym) & set(lg)
print('common case count:', len(common))
mismatches = 0
for case in common:
    notes = {md[case][2], jl[case][2], cs[case][2], ym[case][2], lg[case][2]}
    if len(notes) != 1:
        mismatches += 1
print('note mismatches across common cases:', mismatches)
"

