jl = parse_jsonl('$DIR/audit-v2-s03-t05-evidence-02.jsonl')
cs = parse_csv('$DIR/audit-v2-s03-t05-evidence-03.csv')
ym = parse_yaml('$DIR/audit-v2-s03-t05-evidence-04.yaml')
lg = parse_log('$DIR/audit-v2-s03-t05-evidence-05.log')

