input.command:
cd /tmp && python3 <<'EOF'
import json, re, csv, hashlib
base = "/private/var/folders/sp/k4h4yd5j4bj0zwbwzps0yj8c0000gp/T/lcm-live-92o2us9p/audit-v2-s03/maintenance/inputs/audit-v2-s03/proxy-config-archive/"

# md
md_text = open(base+"audit-v2-s03-t07-evidence-01.md", encoding="utf-8").read()
md_records = {}
for m in re.finditer(r"\*\*(audit-v2-s03-t07-\d{6})\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.*)", md_text):
    case, system, status, note = m.groups()
    md_records[case] = (system, status, note)

# jsonl
jsonl_records = {}
with open(base+"audit-v2-s03-t07-evidence-02.jsonl", encoding="utf-8") as f:
    for line in f:
        line = line.strip()
        if not line: continue
        rec = json.loads(line)
        jsonl_records[rec["case"]] = (rec["system"], rec["status"], rec["note"])

# csv
csv_records = {}
with open(base+"audit-v2-s03-t07-evidence-03.csv", encoding="utf-8", newline="") as f:
    reader = csv.DictReader(f)
    for row in reader:
        csv_records[row["case"]] = (row["system"], row["status"], row["note"])

# yaml (simple line-based parse given known structure)
yaml_text = open(base+"audit-v2-s03-t07-evidence-04.yaml", encoding="utf-8").read()
yaml_records = {}
blocks = re.findall(r"- case: (audit-v2-s03-t07-\d{6})\n  system: (\S+)\n  status: (\S+)\n  note: \"(.*?)\"", yaml_text)
for case, system, status, note in blocks:
    yaml_records[case] = (system, status, note)

# log
log_text = open(base+"audit-v2-s03-t07-evidence-05.log", encoding="utf-8").read()
log_records = {}
for m in re.finditer(r'case=(audit-v2-s03-t07-\d{6}) system=(\S+) status=(\S+) note="(.*?)"', log_text):
    case, system, status, note = m.groups()
    log_records[case] = (system, status, note)

print("counts:", {"md": len(md_records), "jsonl": len(jsonl_records), "csv": len(csv_records), "yaml": len(yaml_records), "log": len(log_records)})

def bounds(d):
    nums = sorted(int(c.split("-")[-1]) for c in d)
    return nums[0], nums[-1], len(nums), nums[-1]-nums[0]+1 == len(nums)

for name, d in [("md", md_records), ("jsonl", jsonl_records), ("csv", csv_records), ("yaml", yaml_records), ("log", log_records)]:
    lo, hi, n, contiguous = bounds(d)
    print(name, "min", lo, "max", hi, "count", n, "contiguous", contiguous)

# cyclic pattern check across all sets combined
combined = {}
for d in (md_records, jsonl_records, csv_records, yaml_records, log_records):
    for case, (system, status, note) in d.items():
        combined.setdefault(case, set()).add((system, status))

mismatch_within_case = [c for c, s in combined.items() if len(s) > 1]
print("cases with inconsistent (system,status) across files:", len(mismatch_within_case))

# Derive mod4 mapping from md file (assumed authoritative reference) and verify against all
mapping = {}
violations = []
for d_name, d in [("md", md_records), ("jsonl", jsonl_records), ("csv", csv_records), ("yaml", yaml_records), ("log", log_records)]:
    for case, (system, status, note) in d.items():
        n = int(case.split("-")[-1])
        mod = n % 4
        key = (system, status)
        if mod not in mapping:
            mapping[mod] = key
        elif mapping[mod] != key:
            violations.append((d_name, case, mod, key, mapping[mod]))
print("mapping (mod4 -> (system,status)):", mapping)
print("violations:", len(violations))
if violations[:5]:
    print(violations[:5])

# note text agreement across common cases (bounded by smallest set = jsonl with 138... wait let's check smallest)
common_cases = set(md_records) & set(jsonl_records) & set(csv_records) & set(yaml_records) & set(log_records)
print("common cases count:", len(common_cases))
note_mismatches = []
for case in common_cases:
    notes = set()
    for d in (md_records, jsonl_records, csv_records, yaml_records, log_records):
        notes.add(d[case][2])
    if len(notes) > 1:
        note_mismatches.append(case)
print("note mismatches among common cases:", len(note_mismatches))

# check md vs yaml case range identical or not (like t05 finding)
md_set = set(md_records)
yaml_set = set(yaml_records)
print("md - yaml:", sorted(md_set - yaml_set))
print("yaml - md:", sorted(yaml_set - md_set))

# Identify smallest bounding set among all 5
sizes = {"md": len(md_records), "jsonl": len(jsonl_records), "csv": len(csv_records), "yaml": len(yaml_records), "log": len(log_records)}
print("sizes sorted:", sorted(sizes.items(), key=lambda kv: kv[1]))
EOF

