import json, re, csv

md_records = {}
with open("audit-v2-s03-t11-evidence-01.md") as f:
    for line in f:
        m = re.match(r"- \*\*(\S+)\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.*)$", line.strip())
        if m:
            case, system, status, note = m.groups()
            md_records[case] = (system, status, note)

jsonl_records = {}
with open("audit-v2-s03-t11-evidence-02.jsonl") as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        d = json.loads(line)
        jsonl_records[d["case"]] = (d["system"], d["status"], d["note"])

csv_records = {}
with open("audit-v2-s03-t11-evidence-03.csv", newline="") as f:
    reader = csv.DictReader(f)
    for row in reader:
        csv_records[row["case"]] = (row["system"], row["status"], row["note"])

yaml_records = {}
with open("audit-v2-s03-t11-evidence-04.yaml") as f:
    lines = f.read().splitlines()[1:]
entry = {}
for line in lines:
    line = line.strip()
    if line.startswith("- case:"):
        if entry:
            yaml_records[entry["case"]] = (entry["system"], entry["status"], entry["note"])
        entry = {"case": line.split(":",1)[1].strip()}
    elif line.startswith("system:"):
        entry["system"] = line.split(":",1)[1].strip()
    elif line.startswith("status:"):
        entry["status"] = line.split(":",1)[1].strip()
    elif line.startswith("note:"):
        entry["note"] = line.split(":",1)[1].strip().strip('"')
if entry:
    yaml_records[entry["case"]] = (entry["system"], entry["status"], entry["note"])

log_records = {}
with open("audit-v2-s03-t11-evidence-05.log") as f:
    for line in f:
        line = line.strip()
        m = re.match(r'case=(\S+) system=(\S+) status=(\S+) note="(.*)"$', line)
        if m:
            case, system, status, note = m.groups()
            log_records[case] = (system, status, note)

print("counts: md=%d jsonl=%d csv=%d yaml=%d log=%d" % (len(md_records), len(jsonl_records), len(csv_records), len(yaml_records), len(log_records)))

def idrange(d):
    nums = sorted(int(c.split("-")[-1]) for c in d)
    return nums[0], nums[-1], (len(nums) == nums[-1]-nums[0]+1)

print("md range:", idrange(md_records))
print("jsonl range:", idrange(jsonl_records))
print("csv range:", idrange(csv_records))
print("yaml range:", idrange(yaml_records))
print("log range:", idrange(log_records))

all_records = {}
for d in (md_records, jsonl_records, csv_records, yaml_records, log_records):
    all_records.update(d)

cycle = {}
violations = []
for case, (system, status, note) in all_records.items():
    num = int(case.split("-")[-1])
    rem = num % 4
    key = (system, status)
    if rem in cycle:
        if cycle[rem] != key:
            violations.append((case, rem, key, cycle[rem]))
    else:
        cycle[rem] = key

print("cycle mapping (rem -> system,status):", cycle)
print("total unique records checked:", len(all_records), "violations:", len(violations))

common = set(md_records) & set(jsonl_records) & set(csv_records) & set(yaml_records) & set(log_records)
print("common cases (all 5 files):", len(common))
mismatches = 0
for c in common:
    notes = {md_records[c][2], jsonl_records[c][2], csv_records[c][2], yaml_records[c][2], log_records[c][2]}
    if len(notes) != 1:
        mismatches += 1
print("note mismatches among common cases:", mismatches)

print("md - yaml:", sorted(set(md_records) - set(yaml_records)))
print("yaml - md:", sorted(set(yaml_records) - set(md_records)))

sizes = {"md":len(md_records),"jsonl":len(jsonl_records),"csv":len(csv_records),"yaml":len(yaml_records),"log":len(log_records)}
print("sizes sorted:", sorted(sizes.items(), key=lambda x: x[1]))
